import argparse

def str2bool(v):
    if isinstance(v, bool):
        return v
    if v.lower() in ('yes', 'true', 't', 'y', '1'):
        return True
    elif v.lower() in ('no', 'false', 'f', 'n', '0'):
        return False
    else:
        raise argparse.ArgumentTypeError('Boolean value expected.')

def parse_joint_training_args():
    parser = argparse.ArgumentParser(description='GILT main architecture: training and evaluation')
    parser.add_argument('--runs', type=int, default=1, help='Number of training runs')
    parser.add_argument('--epochs', type=int, default=50, help='Number of training epochs')
    parser.add_argument('--gpu', type=str, default='0', help='CUDA device index (e.g. 0) or cpu')
    parser.add_argument('--seed', type=int, default=42, help='Random seed')
    parser.add_argument('--hidden', type=int, default=128, help='Hidden dimension')
    parser.add_argument('--num_layers', type=int, default=6, help='Number of GNN layers')
    parser.add_argument('--nhead', type=int, default=4, help='Number of attention heads')
    parser.add_argument('--transformer_layers', type=int, default=2, help='Number of transformer layers')
    parser.add_argument('--mlp_layers', type=int, default=2, help='Number of MLP layers')
    parser.add_argument('--ffn_expansion_ratio', type=int, default=4, choices=[1, 2, 4, 8], help='FFN expansion ratio: hidden_dim * expansion_ratio')
    parser.add_argument('--dp', type=float, default=0.2, help='Dropout rate')
    parser.add_argument('--norm', type=str2bool, default=True, help='Use normalization')
    parser.add_argument('--gnn_norm_affine', type=str2bool, default=True, help='Learnable affine parameters in GNN norm')
    parser.add_argument('--mlp_norm_affine', type=str2bool, default=True, help='Learnable affine parameters in MLP norm')
    parser.add_argument('--optimizer', type=str, default='adam', choices=['adam', 'adamw'])
    parser.add_argument('--lr', type=float, default=1e-05, help='Learning rate')
    parser.add_argument('--weight_decay', type=float, default=0.0001, help='Weight decay')
    parser.add_argument('--eps', type=float, default=1e-08, help='Epsilon for optimizer (term added to denominator for numerical stability)')
    parser.add_argument('--schedule', type=str, default='cosine', choices=['cosine', 'step', 'none'])
    parser.add_argument('--nc_batch_size', type=int, default=2048, help='Node classification batch size')
    parser.add_argument('--lp_batch_size', type=int, default=16384, help='Link prediction batch size')
    parser.add_argument('--test_batch_size', type=int, default=16384, help='Test batch size')
    parser.add_argument('--unseen_test_context_samples', type=int, default=3, help='Average unseen NC test metrics over N random few-shot context resamples (>=1)')
    parser.add_argument('--unseen_test_context_seed_mode', type=str, default='fixed', choices=['per_run', 'fixed'], help='Seed policy for unseen-test context resampling: per_run=independent each run, fixed=deterministic per run from --seed')
    parser.add_argument('--unseen_test_context_seed_base', type=int, default=None, help='Explicit seed base for unseen-test context resampling; overrides --unseen_test_context_seed_mode when set')
    parser.add_argument('--unseen_test_context_seed_bases', type=str, default=None, help='Comma-separated seed bases, one per run, for exact unseen-test context reproduction; overridden by --unseen_test_context_seed_base')
    parser.add_argument('--clip_grad', type=float, default=1.0, help='Gradient clipping')
    parser.add_argument('--enable_nc', type=str2bool, default=True, help='Enable node classification task')
    parser.add_argument('--enable_lp', type=str2bool, default=True, help='Enable link prediction task')
    parser.add_argument('--enable_gc', type=str2bool, default=True, help='Enable graph classification task')
    parser.add_argument('--use_separate_optimizers', type=str2bool, default=True, help='Use separate optimizers for each task with task-specific learning rates')
    parser.add_argument('--lr_nc', type=float, default=None, help='Learning rate for node classification (uses --lr if None)')
    parser.add_argument('--lr_lp', type=float, default=None, help='Learning rate for link prediction (uses --lr if None)')
    parser.add_argument('--lr_gc', type=float, default=None, help='Learning rate for graph classification (uses --lr if None)')
    parser.add_argument('--lambda_nc', type=float, default=1, help='[DEPRECATED] Weight for node classification loss - use --lr_nc instead')
    parser.add_argument('--lambda_lp', type=float, default=1, help='[DEPRECATED] Weight for link prediction loss - use --lr_lp instead')
    parser.add_argument('--nc_train_dataset', type=str, default='ogbn-arxiv,CS,Physics,Computers,Photo,Flickr,USA,Brazil,Europe,Wiki,BlogCatalog,DBLP,FacebookPagePage,Actor,DeezerEurope,LastFMAsia', help='Node classification training datasets')
    parser.add_argument('--nc_test_dataset', type=str, default='Cora,Citeseer,Pubmed,WikiCS', help='Node classification test datasets')
    parser.add_argument('--nc_valid_dataset', type=str, default='', help='Optional held-out node classification validation datasets for model selection (comma-separated, empty = disabled)')
    parser.add_argument('--nc_graph_direction', type=str, default='undirected', choices=['undirected', 'directed'], help='Node classification graph direction mode for adjacency/message passing ablation')
    parser.add_argument('--lp_train_dataset', type=str, default='ogbn-arxiv,CS,Physics,Computers,Photo,Flickr,USA,Brazil,Europe,Wiki,BlogCatalog,DBLP,FacebookPagePage,Actor,DeezerEurope,LastFMAsia', help='Link prediction training datasets')
    parser.add_argument('--lp_test_dataset', type=str, default='Cora,Citeseer,Pubmed,ogbl-collab', help='Link prediction test datasets')
    parser.add_argument('--lp_valid_dataset', type=str, default='', help='Optional held-out link prediction validation datasets for model selection (comma-separated, empty = disabled)')
    parser.add_argument('--gc_valid_dataset', type=str, default='', help='Optional held-out graph classification validation datasets for model selection (comma-separated, empty = disabled)')
    parser.add_argument('--context_num', type=int, default=5, help='Number of context nodes')
    parser.add_argument('--head_num_layers', type=int, default=0, help='Number of MLP layers in task-specific heads')
    parser.add_argument('--nc_head_num_layers', type=int, default=0, help='Override head_num_layers for node classification head')
    parser.add_argument('--lp_head_num_layers', type=int, default=2, help='Override head_num_layers for link prediction head (default: use --head_num_layers)')
    parser.add_argument('--gc_head_num_layers', type=int, default=1, help='Override head_num_layers for graph classification head (default: use --head_num_layers)')
    parser.add_argument('--normalize_class_h', type=str2bool, default=True, help='Normalize class embeddings')
    parser.add_argument('--use_cs', type=str2bool, default=True, help='Apply Correct & Smooth post-processing. Decision is validation-based: only uses C&S if it improves validation accuracy (no test leakage)')
    parser.add_argument('--cs_num_iters', type=int, default=50, help='Number of label propagation iterations for C&S')
    parser.add_argument('--cs_alpha', type=float, default=0.5, help='Blending factor for C&S (higher = more emphasis on previous iteration)')
    parser.add_argument('--use_full_pca', type=str2bool, default=False, help='Use full PCA decomposition')
    parser.add_argument('--test_process_test_only', type=str2bool, default=True, help='For test datasets, only process the test split to preserve split isolation and improve efficiency')
    parser.add_argument('--pca_device', type=str, default='gpu', choices=['cpu', 'gpu'], help='Device to perform PCA computation (cpu=Incremental PCA, gpu=torch.pca_lowrank)')
    parser.add_argument('--incremental_pca_batch_size', type=int, default=10000, help='Batch size for CPU Incremental PCA')
    parser.add_argument('--pca_sample_threshold', type=int, default=100000, help='Threshold for using sampled PCA on GPU')
    parser.add_argument('--use_pca_cache', type=str2bool, default=True, help='Enable PCA result caching for faster subsequent runs')
    parser.add_argument('--pca_cache_dir', type=str, default='./pca_cache', help='Directory to store PCA cache files')
    parser.add_argument('--normalize_data', type=str2bool, default=True, help='Normalize input data')
    parser.add_argument('--use_batchnorm', type=str2bool, default=True, help='Use BatchNorm instead of LayerNorm')
    parser.add_argument('--edge_dropout_rate', type=float, default=0.0, help='Edge dropout rate for data augmentation (0.0-0.5). Set to 0.0 to disable.')
    parser.add_argument('--edge_dropout_enabled', type=str2bool, default=True, help='Enable edge dropout augmentation during training')
    parser.add_argument('--feature_dropout_rate', type=float, default=0.0, help='Feature dropout rate for data augmentation (0.0-0.8). Set to 0.0 to disable.')
    parser.add_argument('--feature_dropout_enabled', type=str2bool, default=True, help='Enable feature dropout augmentation during training (applied after projection)')
    parser.add_argument('--static_embedding_cache', type=str, default='auto', choices=['off', 'auto', 'force'], help='Static embedding cache mode for NC/LP/GC: off=disabled, auto=enable only for safe parameter-free settings, force=override conservative model-type checks (still requires no trainable encoder/projection params)')
    parser.add_argument('--use_test_time_augmentation', type=str2bool, default=True, help='Apply test-time augmentation during final evaluation: create multiple augmented versions and aggregate predictions')
    parser.add_argument('--tta_num_augmentations', type=int, default=5, help='Number of augmented versions to create at test time (will be aggregated with original graph)')
    parser.add_argument('--tta_aggregation', type=str, default='probs', choices=['logits', 'probs', 'voting'], help='TTA aggregation strategy: logits (average logits before softmax), probs (average probabilities), voting (majority vote)')
    parser.add_argument('--tta_include_original', type=str2bool, default=True, help='Include original graph in TTA aggregation (True) or only use augmented versions (False)')
    parser.add_argument('--tta_gate_by_valid', type=str2bool, default=True, help='When TTA is enabled, only trust TTA if it improves the validation metric (per dataset)')
    parser.add_argument('--tta_apply_input_normalization_to_views', type=str2bool, default=True, help='Apply the same final input normalization step as the main NC path to augmented TTA views after PCA/padding')
    parser.add_argument('--tta_linear_projection', type=str2bool, default=True, help='Use linear-only NC TTA projections by disabling the random activation after XW+b')
    parser.add_argument('--split_rebalance_strategy', type=str, default='legacy', choices=['smallest_for_valid', 'legacy', 'original'], help='How to rebalance dataset splits for pretraining: smallest_for_valid (use smallest split for validation), legacy (train+valid for training, test for validation), original (keep original splits)')
    parser.add_argument('--context_neg_ratio', type=int, default=3, help='Negative sampling ratio for context')
    parser.add_argument('--train_neg_ratio', type=int, default=3, help='Negative sampling ratio for training')
    parser.add_argument('--context_k', type=int, default=5, help='Number of context samples for link prediction')
    parser.add_argument('--remove_context_from_train', type=str2bool, default=True, help='Remove context from training set')
    parser.add_argument('--mask_target_edges', type=str2bool, default=True, help='Mask target edges during message passing')
    parser.add_argument('--lp_metric', type=str, default='auto', choices=['auto', 'auc', 'acc', 'hits@20', 'hits@50', 'hits@100', 'mrr'], help='Metric to use for link prediction evaluation (auto=dataset default, auc, acc, or hits@K/mrr)')
    parser.add_argument('--lp_use_test_time_augmentation', type=str2bool, default=True, help='Apply LP test-time augmentation by averaging per-edge scores across augmented feature views')
    parser.add_argument('--lp_tta_num_augmentations', type=int, default=None, help='Number of LP TTA augmented views; None uses --tta_num_augmentations')
    parser.add_argument('--lp_tta_normalize_views', type=str2bool, default=True, help='Normalize LP TTA augmented views after PCA using the same final normalization mode as input preprocessing')
    parser.add_argument('--lp_tta_linear_projection', type=str2bool, default=True, help='Use linear-only LP TTA projections by disabling the random activation after XW+b')
    parser.add_argument('--lp_tta_context_gate', type=str2bool, default=False, help='Keep only LP TTA views whose context-edge dot AUC is no worse than the original view')
    parser.add_argument('--lp_tta_context_gate_tolerance', type=float, default=0.0, help='Tolerance for LP TTA context gate: keep view if context AUC + tolerance >= original context AUC')
    parser.add_argument('--lp_tta_train_gate', type=str2bool, default=True, help='Keep only LP TTA views that preserve Hits@K on a sampled train-edge gate set')
    parser.add_argument('--lp_tta_train_gate_pos_samples', type=int, default=4096, help='Number of positive train edges sampled for LP TTA train gate')
    parser.add_argument('--lp_tta_train_gate_neg_ratio', type=float, default=1.0, help='Negative-to-positive sample ratio for LP TTA train gate')
    parser.add_argument('--lp_tta_train_gate_hits_k', type=int, default=20, help='Hits@K used by LP TTA train gate')
    parser.add_argument('--lp_tta_train_gate_tolerance', type=float, default=-0.01, help='Tolerance for LP TTA train gate: keep view if train-gate Hits@K + tolerance >= original')
    parser.add_argument('--mplp_signature_dim', type=int, default=1024, help='Dimension of random signature vectors for MPLP')
    parser.add_argument('--mplp_num_hops', type=int, default=2, help='Number of hops for MPLP structure propagation')
    parser.add_argument('--mplp_feature_combine', type=str, default='hadamard', choices=['hadamard', 'concat'], help='Method to combine node features in MPLP')
    parser.add_argument('--mplp_prop_type', type=str, default='combine', choices=['exact', 'combine'], help='Structural feature type for MPLP head (default: combine)')
    parser.add_argument('--mplp_signature_sampling', type=str, default='torchhd', choices=['torchhd', 'gaussian'], help='Signature sampling method for MPLP (default: torchhd)')
    parser.add_argument('--mplp_use_subgraph', type=str2bool, default=True, help='Use 2-hop subgraph for MPLP structural features (default: True)')
    parser.add_argument('--mplp_use_degree', type=str, default='mlp', choices=['none', 'aa', 'ra', 'mlp'], help='Degree-based node weighting for MPLP structural features')
    parser.add_argument('--gc_train_dataset', type=str, default='bace,bbbp,tox21,toxcast,clintox,muv,sider', help='Graph classification training datasets')
    parser.add_argument('--gc_test_dataset', type=str, default='hiv,pcba', help='Graph classification test datasets')
    parser.add_argument('--gc_batch_size', type=int, default=1024, help='Graph classification batch size')
    parser.add_argument('--gc_test_batch_size', type=int, default=4096, help='Graph classification test batch size')
    parser.add_argument('--graph_pooling', type=str, default='max', choices=['mean', 'max', 'sum'], help='Graph pooling method')
    parser.add_argument('--gc_metric', type=str, default='auc', choices=['auto', 'auc', 'ap', 'accuracy'], help='Graph classification metric override (auto=dataset default)')
    parser.add_argument('--gc_use_test_time_augmentation', type=str2bool, default=True, help='Apply graph classification TTA by averaging logits across augmented node-feature views')
    parser.add_argument('--gc_tta_num_augmentations', type=int, default=None, help='Number of GC TTA augmented views; None uses --tta_num_augmentations')
    parser.add_argument('--gc_tta_normalize_views', type=str2bool, default=True, help='Normalize GC TTA augmented node-feature views after PCA using the same final normalization mode')
    parser.add_argument('--gc_tta_linear_projection', type=str2bool, default=False, help='Use linear-only GC TTA projections by disabling the random activation after XW+b')
    parser.add_argument('--gc_tta_feature_projection', type=str2bool, default=True, help='Use random feature-projection views in GC TTA. Disable for edge-drop-only GC TTA')
    parser.add_argument('--gc_tta_edge_dropout_rate', type=float, default=0.0, help='Per-edge dropout rate for augmented GC TTA views. The original view is unchanged')
    parser.add_argument('--lambda_gc', type=float, default=0.41834063194474214, help='Weight for graph classification loss')
    parser.add_argument('--context_graph_num', type=int, default=5, help='Number of context graphs for graph classification')
    parser.add_argument('--gc_multitask_vectorized', type=str2bool, default=True, help='Enable vectorized multi-task prototypical GC (single BCEWithLogits over all tasks, e.g., PCBA)')
    parser.add_argument('--gc_vec_task_chunk_size', type=int, default=10, help='Task chunk size for vectorized GC PFN backward (0 = disabled, keeps original all-task backward)')
    parser.add_argument('--ogb_root', type=str, default='./dataset/ogb', help='Root directory for OGB datasets')
    parser.add_argument('--nc_context_overrides', type=str, default=None, help='Per-dataset context overrides for NC: "dataset1:shots1,dataset2:shots2"')
    parser.add_argument('--lp_context_overrides', type=str, default=None, help='Per-dataset context overrides for LP: "dataset1:shots1,dataset2:shots2"')
    parser.add_argument('--gc_context_overrides', type=str, default=None, help='Per-dataset context overrides for GC: "dataset1:shots1,dataset2:shots2"')
    parser.add_argument('--context_refresh_interval', type=int, default=1, help='Refresh contexts every N epochs (0 = never refresh)')
    parser.add_argument('--context_batch_refresh_interval', type=int, default=0, help='Refresh contexts every N batches within each task (0 = disabled)')
    parser.add_argument('--context_sampling_plan', type=str, default='ori', choices=['ori', 'random', 'decay'], help='Context sampling strategy: ori=original fixed, random=random sampling, decay=gradual decay')
    parser.add_argument('--context_bounds', type=str, default='(5,20)(5,20)(5,20)', help='Context bounds for NC/LP/GC: (lower,upper)(lower,upper)(lower,upper). Used for random sampling range and decay start/end.')
    parser.add_argument('--save_checkpoint', type=str2bool, default=True, help='Save model checkpoints')
    parser.add_argument('--checkpoint_dir', type=str, default='./checkpoints', help='Checkpoint directory')
    parser.add_argument('--checkpoint_name', type=str, default=None, help='Custom checkpoint name')
    parser.add_argument('--load_checkpoint', type=str, default=None, help='Path to checkpoint to load')
    parser.add_argument('--use_pretrained_model', type=str2bool, default=False, help='Use pretrained model')
    args = parser.parse_args()
    vars(args).update({'augmentation_max_dim': 1000, 'feature_dropout_type': 'channel_wise', 'gc_sim': 'dot', 'gc_train_eval_max_batches': 10, 'gc_train_eval_shuffle': True, 'lp_cache_mask_target_only_for_mplp': False, 'lp_orthogonal_noise_dim': 128, 'nc_eval_profile_view_interval': 0, 'orthogonal_push': 0, 'padding_strategy': 'zero', 'projection_large_dim': 512, 'projection_small_dim': 128, 'quantile_norm_before_padding': True, 'tta_distribution_debug': False, 'verbose_edge_dropout': False, 'verbose_feature_dropout': False})
    return args
